import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"ToDos — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"ToDos — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/todos"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"ToDos — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/todos"}]]},"headers":[],"relativePath":"user-guide/todos.md","filePath":"user-guide/todos.md","lastUpdated":1787698998000}'),s={name:"user-guide/todos.md"};function n(d,e,i,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="todos-—-user-guide" tabindex="-1">ToDos — User Guide <a class="header-anchor" href="#todos-—-user-guide" aria-label="Permalink to &quot;ToDos — User Guide&quot;">​</a></h1><h2 id="who-can-use-todos" tabindex="-1">Who can use ToDos <a class="header-anchor" href="#who-can-use-todos" aria-label="Permalink to &quot;Who can use ToDos&quot;">​</a></h2><p>Your workspace must have the <strong>ToDos</strong> module installed (included by default on new workspaces). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code> as needed).</p><ul><li>Regular users only see <strong>their own</strong> to-dos (items they created).</li><li>The <strong>workspace owner</strong> can open ToDos and see everyone’s items (read-only for others’ cards).</li><li>Only the person who created a to-do can edit or delete it.</li></ul><h2 id="board-list" tabindex="-1">Board &amp; list <a class="header-anchor" href="#board-list" aria-label="Permalink to &quot;Board &amp; list&quot;">​</a></h2><p>Open <strong>ToDos</strong> from the sidebar. The default view is the <strong>Board</strong> (columns by status). Switch to <strong>List</strong> for a table.</p><ul><li>Search by title or description</li><li>Filter by status, priority, <strong>tag</strong>, and <strong>Overdue</strong> (open / in-progress items past their due date)</li><li>Board cards show colored <strong>tag</strong> chips</li><li>Drag a card to another column to auto-save the status change (only your own to-dos; no drawer opens)</li></ul><p>Status labels in the UI:</p><table tabindex="0"><thead><tr><th>Value</th><th>Label</th></tr></thead><tbody><tr><td><code>open</code></td><td>To Do</td></tr><tr><td><code>in_progress</code></td><td>In Progress</td></tr><tr><td><code>completed</code></td><td>Completed</td></tr><tr><td><code>cancelled</code></td><td>Cancelled</td></tr></tbody></table><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New to-do</strong></li><li>Enter title (required) and optional description, status, priority, and due date (workspace timezone from Settings → General). <strong>Overdue</strong> means that due instant has already passed — a to-do due later today is not overdue.</li><li>Optionally assign <strong>tags</strong> (colored labels). Create a new tag inline with a name and color, then tick it</li><li>Save</li></ol><p>Edit from the row menu or the record page — only when you are the creator. Owners viewing someone else’s to-do see a read-only detail panel.</p><p>Tags are a <strong>ToDos-only</strong> catalog (separate from Tasks / Leads / Opportunities). In this release you can <strong>create and assign</strong> tags inline; there is no Manage Tags screen to rename or delete them. The record page shows tag badges — change assignments from Edit.</p><h2 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h2><p>Soft-delete from the list row menu. Only the creator can delete. The workspace owner cannot delete another user’s to-do.</p>',15)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
